slow_pseudocode:
# BAD: XBLOCK >> xnumel=9 forces compiler to allocate 80 registers/thread
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 128,  'YBLOCK': 64}, num_warps=4),
        triton.Config({'XBLOCK': 256,  'YBLOCK': 64}, num_warps=4),
        triton.Config({'XBLOCK': 512,  'YBLOCK': 64}, num_warps=8),
        triton.Config({'XBLOCK': 1024, 'YBLOCK': 64}, num_warps=8),
    ],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(..., YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    xindex = tl.program_id(0) * XBLOCK + tl.arange(0, XBLOCK)[None, :]
    # XBLOCK=1024 with xnumel=9: 1015/1024 threads masked, 80 regs/thread
    # Theoretical occupancy drops to 37.5%, duration 10.91 us

fast_pseudocode:
# GOOD: XBLOCK bounded to values near xnumel=9 (1 or 16)
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 1,  'YBLOCK': 64},  num_warps=4),
        triton.Config({'XBLOCK': 1,  'YBLOCK': 128}, num_warps=4),
        triton.Config({'XBLOCK': 16, 'YBLOCK': 64},  num_warps=4),
        triton.Config({'XBLOCK': 16, 'YBLOCK': 128}, num_warps=4),
    ],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(..., YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    xindex = tl.program_id(0) * XBLOCK + tl.arange(0, XBLOCK)[None, :]
    # XBLOCK=16 with xnumel=9: 7/16 threads masked, 16 regs/thread
    # Theoretical occupancy 100%, duration 2.94 us
